INSERT INTO instruments (instrument_id, authority_id, lg_id, kind, force, title, notes) VALUES ($q$MICC_PLANNING_SCHEME_2020$q$, $q$MICC$q$, $q$MOUNT_ISA$q$, 'PLANNING_SCHEME', 'STATUTORY_INSTRUMENT', $q$City of Mount Isa Planning Scheme 2020$q$, $q$Council page (read via WebFetch) states Council 'adopted the City of Mount Isa Planning Scheme 2020 on 12 February 2020' and it commenced Monday 9 March 2020; it lists a Major Amendment planned for 2026-2027 (housing focus) but no amendment in force. Every page header of the official no-maps PDF reads 'City of Mount Isa Planning Scheme – 09 March 2020' (413 pages, PDF created 25 Feb 2020, modified 28 Feb 2020, author andrewstownplanning). The official council server (Akamai) returned 403 to every scripted client from this machine, so the official no-maps PDF was retrieved as a byte-for-byte Internet Archive capture of the council URL (snapshot 20250407213909, id_ raw mode; SHA-256 ca488ad3fb04c260acd7532ca3abf9c59d3ed2a313e45d8b4adc3485e7cd069b, 11,823,884 bytes). The live council page still links the same /v/1/ file name, so this is believed to be the current text. QHC: the scheme text contains no reference to the Queensland Housing Code (0 matches for 'Housing Code'); it refers only to the QDC. No QHC adoption found.$q$);
