SELECT define_rule($q${"rule_id": "MICC.micc_ra_ao23_1_garage_behind_front_building_line", "instrument_version": "MICC_PLANNING_SCHEME_2020@2020-03-09", "topic": "SETBACK.FRONTAGE", "title": "Table 9.3.6.1 PO 23 / AO 23.1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "garage setback >= dwelling front building line OR opening <= min(6 m, 0.6 x frontage)", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2020-03-09", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MOUNT_ISA"}, {"level": "ZONE", "zone": "MICC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "MICC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "MICC:TOWNSHIP"}], "subjects": ["CLASS_10A"], "sources": [{"key": "micc_ra_ao23_1_garage_behind_front_building_line", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"garage_position_relative_to_front_building_line\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"garage located behind the front building line\", \"OR garage opening <= lesser of 6 m or 60% of road frontage (alternative compliance path)\"], \"exceptions\": [], \"formula_text\": \"garage setback >= dwelling front building line OR opening <= min(6 m, 0.6 x frontage)\"}\nStructure scope 'Garages (domestic outbuildings)' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: YES - s1.6(4) names 'Low density residential zone: assessment of a Class 10A building' and 'Medium density residential zone: assessment of a Class 10A building', and Table 5.7.1 makes PO 22 and PO 23 the benchmarks for Class 10a building work in those zones (Township is in Table 5.7.1 but not s1.6(4))\nResearcher notes: Not a numeric setback; a relative siting control with an either/or alternative. Recorded because it is the only front-siting control for Class 10a building work. Related AO 23.2 (carports: height 4.5 m, opening, no door facing primary frontage) and AO 23.3 (pools forward of the front building line max 1.5 m height) set no setback and are not recorded. AO 22.1 (domestic outbuildings max 4.5 m high, 100 m2) out of scope."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$MICC.micc_ra_ao23_1_garage_behind_front_building_line@2020-03-09$q$;
