SELECT define_provision($q$MICC_PLANNING_SCHEME_2020@2020-03-09$q$, $q$Table 5.7.1; Table 9.3.6.1 PO 22-PO 23$q$, 'OTHER', $q$(No side or rear boundary setback is stated in Residential activities code PO 22 or PO 23, the only assessment benchmarks Table 5.7.1 applies to construction of a Class 10a building in these zones; the QDC boundary clearances apply.)$q$, 'UNVERIFIED', $q$Table 5.7.1 printed p104 / PDF p110; PO 22-23 printed p279-280 / PDF p289-290$q$, NULL, $q$9.3.6 Residential activities code (PO 22 and PO 23 as applied by Table 5.7.1)$q$, NULL, $q$https://www.mountisa.qld.gov.au/files/assets/public/v/1/development/documents/city_of_mount_isa_planning_scheme__no_maps_.pdf$q$, $q$$q$, $q$micc_class10a_bw_side_rear_absent_qdc$q$);
SELECT define_rule($q${"rule_id": "MICC.micc_class10a_bw_side_rear_absent_qdc", "instrument_version": "MICC_PLANNING_SCHEME_2020@2020-03-09", "topic": "SETBACK.SIDE", "title": "Table 5.7.1; Table 9.3.6.1 PO 22-PO 23", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "(No side or rear boundary setback is stated in Residential activities code PO 22 or PO 23, the only assessment benchmarks Table 5.7.1 applies to construction of a Class 10a building in these zones; the QDC boundary clearances apply.)", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2020-03-09", "verification": "UNVERIFIED", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MOUNT_ISA"}, {"level": "ZONE", "zone": "MICC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "MICC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "MICC:TOWNSHIP"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "micc_class10a_bw_side_rear_absent_qdc", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"side_rear_boundary_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"applies to side AND rear boundaries\", \"stand-alone Class 10a building work\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Class 10a building (as defined by the Building Code of Australia)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO - no side/rear provision exists in PO 22/PO 23\nResearcher notes: Absence rule. In all other zones Class 10a building work is accepted development (no scheme requirements) unless an overlay applies, so QDC MP1.1/1.2 governs there too. Only when a Class 10a structure forms part of a residential use assessed under the Residential activities code would AO 4.1/AO 4.2 apply (subject to the QDC note)."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$MICC.micc_class10a_bw_side_rear_absent_qdc@2020-03-09$q$;

INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$MOUNT_ISA$q$, $q$MICC_PLANNING_SCHEME_2020$q$, 'MEDIUM', $q$Scope of Table 9.3.6.3 note 'the Queensland Development Code setbacks apply for dwelling houses and dual occupancies': does it displace AO 4.1 road setbacks as well as AO 4.2 side/rear, and does it reach Class 10a outbuildings ancillary to a dwelling house? Default reading: yes for side/rear, so dwelling-house outbuildings use QDC; all AO 4.1/4.2 rules flagged needs_manual_review.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$MOUNT_ISA$q$, $q$MICC_PLANNING_SCHEME_2020$q$, 'MEDIUM', $q$Table 5.7.1 makes Class 10a building work in the Township zone accepted subject to PO 22/PO 23, but s1.6(4) lists only Low density and Medium density residential zones as containing building assessment provisions.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$MOUNT_ISA$q$, $q$MICC_PLANNING_SCHEME_2020$q$, 'MEDIUM', $q$Table 9.3.6.3 lot-width bands are drafted as 'Not greater than 12.5 metres, but less than 15.0 metres' and 'Not greater than 15.0 metres, but less than 20 metres' (presumably 'greater than').$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$MOUNT_ISA$q$, $q$MICC_PLANNING_SCHEME_2020$q$, 'MEDIUM', $q$Grouping of 'If ...' conditions in the Part 5 tables (e.g. whether the 50m2 expansion condition attaches to Dwelling house in Local centre, Principal centre and Mixed use) is ambiguous in the PDF layout.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$MOUNT_ISA$q$, $q$MICC_PLANNING_SCHEME_2020$q$, 'MEDIUM', $q$The official council site (Akamai) returns 403 to all scripted clients from this host; text was read from an Internet Archive byte copy (April 2025) of the official no-maps PDF. Before publishing, a curator should download the current PDF manually from https://www.mountisa.qld.gov.au/files/assets/public/v/1/development/documents/city_of_mount_isa_planning_scheme__no_maps_.pdf in a browser and confirm the SHA-256 (ca488ad3...069b) or diff pages 277, 289-290 and 296.$q$);
